'use client';

import { useMemo } from 'react';

interface LightingProps {
  preset: 'warm' | 'cool' | 'neutral' | 'dramatic';
}

export function Lighting({ preset }: LightingProps) {
  const config = useMemo(() => {
    switch (preset) {
      case 'warm':
        return {
          ambient: { intensity: 0.4, color: '#FFE4C4' },
          directional: { intensity: 1.2, color: '#FFF8DC', position: [5, 10, 5] as [number, number, number] },
          fill: { intensity: 0.3, color: '#FFE4B5', position: [-5, 5, -5] as [number, number, number] },
        };
      case 'cool':
        return {
          ambient: { intensity: 0.5, color: '#E0F2FE' },
          directional: { intensity: 1, color: '#F0F9FF', position: [5, 10, 5] as [number, number, number] },
          fill: { intensity: 0.4, color: '#DBEAFE', position: [-5, 5, -5] as [number, number, number] },
        };
      case 'dramatic':
        return {
          ambient: { intensity: 0.2, color: '#1a1a2e' },
          directional: { intensity: 1.5, color: '#FFD700', position: [3, 8, 3] as [number, number, number] },
          fill: { intensity: 0.2, color: '#4B0082', position: [-3, 4, -3] as [number, number, number] },
        };
      default: // neutral
        return {
          ambient: { intensity: 0.6, color: '#ffffff' },
          directional: { intensity: 1, color: '#ffffff', position: [5, 10, 5] as [number, number, number] },
          fill: { intensity: 0.3, color: '#e0e0e0', position: [-5, 5, -5] as [number, number, number] },
        };
    }
  }, [preset]);

  return (
    <>
      <ambientLight 
        intensity={config.ambient.intensity} 
        color={config.ambient.color} 
      />
      <directionalLight
        position={config.directional.position}
        intensity={config.directional.intensity}
        color={config.directional.color}
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
        shadow-camera-far={50}
        shadow-camera-left={-20}
        shadow-camera-right={20}
        shadow-camera-top={20}
        shadow-camera-bottom={-20}
      />
      <pointLight
        position={config.fill.position}
        intensity={config.fill.intensity}
        color={config.fill.color}
      />
    </>
  );
}
